begin;
select plan(12);
insert into auth.users(id) values ('55555555-5555-5555-5555-555555555555');
select ok(public.reserve_ai_budget('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','55555555-5555-5555-5555-555555555555',1000000),'first reservation authorizes one request');
select ok(not public.reserve_ai_budget('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','55555555-5555-5555-5555-555555555555',1000000),'retry does not authorize duplicate provider call');
select throws_ok($$select public.reserve_ai_budget('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','55555555-5555-5555-5555-555555555555',1)$$,'22023','AI request mismatch','mismatched retry fails');
select lives_ok($$select public.finish_ai_budget('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',200000)$$,'settle verified cost');
select lives_ok($$select public.finish_ai_budget('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',200000)$$,'duplicate settlement idempotent');
select is((select spent_micro_usd from public.ai_budget_months),200000::bigint,'charged only once');
select is((select reserved_micro_usd from public.ai_budget_months),0::bigint,'unused reservation released');
select throws_ok($$select public.finish_ai_budget('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',0)$$,'22023','AI charge mismatch','settled cost cannot be erased');
update public.ai_budget_months set spent_micro_usd=25000000;
select throws_ok($$select public.reserve_ai_budget('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','55555555-5555-5555-5555-555555555555',1)$$,'54000','AI monthly budget reached','budget rejects even one micro-dollar beyond cap');
set local role authenticated;
select throws_ok($$select public.reserve_ai_budget('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','55555555-5555-5555-5555-555555555555',1)$$,'42501','permission denied for function reserve_ai_budget','browser cannot authorize spend');
select throws_ok($$select public.finish_ai_budget('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',0)$$,'42501','permission denied for function finish_ai_budget','browser cannot erase spend');
select throws_ok($$select * from public.ai_budget_requests$$,'42501','permission denied for table ai_budget_requests','browser cannot read request ledger');
reset role;
select * from finish();
rollback;
